#!/usr/bin/env python3
"""
build_dashboard.py — EP Case Dashboard generator
Usage: python build_dashboard.py <path-to-excel.xlsx> [--output path.html]

Dependencies: pandas, openpyxl
Install:      pip install pandas openpyxl
"""
import base64
import glob
import json
import os
import sys
import argparse
import subprocess
from datetime import datetime, date
from pathlib import Path

# System python3 may not have pandas; re-exec under the project venv if needed.
try:
    import pandas as pd  # type: ignore
except ModuleNotFoundError:
    _venv_py = Path(__file__).resolve().parent / ".venv" / "bin" / "python3"
    if not _venv_py.exists() or sys.prefix != sys.base_prefix:
        sys.exit("pandas not installed. Run: python3 -m venv .venv && "
                 ".venv/bin/python3 -m pip install pandas openpyxl")
    os.execv(str(_venv_py), [str(_venv_py), str(Path(__file__).resolve()), *sys.argv[1:]])

FAVICON_B64 = ""

HLOGO_B64 = ""

BW_LOGO_B64 = ""

HTML_TEMPLATE = (Path(__file__).resolve().parent / "dashboard.html.tmpl").read_text(encoding="utf-8").lstrip()


# ---------------------------------------------------------------------------
# Data pipeline
# ---------------------------------------------------------------------------

REQUIRED_COLUMNS = [
    "Name",
    "Actual End Date Time",
    "Account: Account Name",
    "Physician: CARTODAY Affiliation Name",
    "Primary CAS: Name",
    "Primary Case Sub Type",
    "BWI Ablation Catheter",
]

PROCEDURE_MAP = {
    "AFib - Paroxysmal": "AF",
    "AFib - Persistent": "AF",
    "Concomitant AFIB Paroxysmal": "Con. AF",
    "Concomitant AFIB Persistent": "Con. AF",
    "Atrial Tach Right Side": "AT",
    "Atrial Tach Left Side": "AT",
    "VT Idiopathic / PVC": "PVC",
    "VT Ischemic": "VT",
    "VT Non-Ischemic": "VT",
    "Typical Flutter": "AFL",
    "Atypical Flutter": "AAFL",
    "LAAO": "Structural",
    "LAAO + ULS": "Structural",
    "Evoque": "Structural",
    "ASD": "Structural",
    "TAVR": "Structural",
    "TTVR": "Structural",
    "Bi-V Pacing": "Structural",
    "AVRT-WPW": "WPW",
    "AV Node Ablation": "AV Node",
    "AVNRT": "AVNRT",
    "Other": "Other",
}

WORK_TYPE_MAP = {
    "A FIB": "AF",
    "V TACH": "VT",
    "A Flutter": "AFL",
    "Lt A FLUTTER": "AAFL",
    "Left AT": "AT",
    "WPW": "WPW",
    "AV NODE": "AV Node",
    "PVC": "PVC",
    "SVT": "SVT",
}


def _norm_name(s):
    if s is None or (isinstance(s, float) and pd.isna(s)):
        return ""
    s = str(s).strip()
    if s.isupper():
        s = s.title()
    parts = s.split()
    if len(parts) >= 2:
        middle = [p for p in parts[1:-1] if len(p.replace(".", "")) > 1]
        return " ".join([parts[0]] + middle + [parts[-1]])
    return s


def _dr_lastname(name):
    n = _norm_name(name)
    if not n:
        return ""
    return "Dr. " + n.split()[-1]


def _first_name(name):
    n = _norm_name(name)
    return n.split()[0] if n else ""


def _short_date(d):
    return f"{d.month}/{d.day}"


def _validate_schema(df, xlsx_path):
    missing = [c for c in REQUIRED_COLUMNS if c not in df.columns]
    if missing:
        raise ValueError(
            f"\n[Schema error] {xlsx_path}\n"
            f"  Missing required columns: {missing}\n"
            f"  Found columns: {list(df.columns)}\n"
            f"  → Check that the source xlsx still uses the expected column names "
            f"(sheet 'Case data for dashboard', header row 9)."
        )


def load_data(xlsx_path):
    df = pd.read_excel(xlsx_path, sheet_name="Case data for dashboard", header=8)
    _validate_schema(df, xlsx_path)

    junk = df["Name"].isin(["Total"]) | df["Name"].astype(str).str.contains(
        "Copyright|Confidential|Do Not Distribute", na=False
    )
    df = df[~junk]

    df["Name"] = df["Name"].astype(str).str.strip()
    df = df[df["Name"] == "Los Angeles, CA - KA"].copy()

    date_col = "Actual End Date Time"
    df = df[df[date_col].notna()].copy()
    df["date"] = pd.to_datetime(df[date_col], errors="coerce")
    df = df[df["date"].notna()].copy()
    df = df[df["date"] >= "2024-01-01"].copy()

    df = df.rename(columns={
        "Account: Account Name": "hospital",
        "Physician: CARTODAY Affiliation Name": "physician",
        "Primary CAS: Name": "cas",
        "Primary Case Sub Type": "procedure",
        "Primary Procedure: Work Type Name": "work_type",
        "BWI Ablation Catheter": "bwi_catheter",
    })
    df["work_type"] = df["work_type"].fillna("").astype(str).str.strip()
    df["bwi_catheter"] = df["bwi_catheter"].fillna("").astype(str)
    df["is_varipulse"] = df["bwi_catheter"].str.contains("VARIPULSE", case=False, na=False)
    df["physician"] = df["physician"].apply(_norm_name)
    df["cas"] = df["cas"].apply(_norm_name)
    df = df[df["cas"] != ""].copy()
    df = df[df["procedure"].notna() & (df["procedure"].astype(str).str.strip() != "")].copy()

    other_mask = df["procedure"] == "Other"
    df.loc[other_mask, "procedure"] = (
        df.loc[other_mask, "work_type"].map(WORK_TYPE_MAP).fillna("Other")
    )

    known_chip_names = set(WORK_TYPE_MAP.values())
    unmapped = sorted(set(df["procedure"]) - set(PROCEDURE_MAP.keys()) - known_chip_names)
    if unmapped:
        print(f"      ⚠️  Unmapped Sub Types (coerced to 'Other'): {unmapped}")

    def _map_procedure(val):
        if val in PROCEDURE_MAP:
            return PROCEDURE_MAP[val]
        if val in known_chip_names:
            return val
        return "Other"

    df["procedure"] = df["procedure"].apply(_map_procedure)
    df["year"] = df["date"].dt.year
    df["month"] = df["date"].dt.month
    df["ym"] = df["date"].dt.strftime("%Y-%m")
    return df


def compute_aggregates(df):
    last_date = df["date"].max()
    last_year = int(last_date.year)
    last_month = int(last_date.month)
    last_day = int(last_date.day)

    def mtd_f(d, y, m, day):
        return d[(d["year"] == y) & (d["month"] == m) & (d["date"].dt.day <= day)]

    def ytd_f(d, y, day_end):
        return d[(d["year"] == y) & (d["date"].dt.normalize() <= pd.Timestamp(y, last_month, day_end))]

    mtd_cy = mtd_f(df, last_year, last_month, last_day)
    mtd_ly = mtd_f(df, last_year - 1, last_month, last_day)
    mtd_ly_full = df[(df["year"] == last_year - 1) & (df["month"] == last_month)]
    ytd_cy = ytd_f(df, last_year, last_day)
    ytd_ly = ytd_f(df, last_year - 1, last_day)

    hospitals_all = sorted(df["hospital"].unique())
    region_ytd_total = len(ytd_cy)

    meta = {
        "last_date": last_date.strftime("%Y-%m-%d"),
        "last_year": last_year,
        "last_month": last_month,
        "last_day": last_day,
        "total_cases": len(df),
        "hospitals": hospitals_all,
        "n_hospitals": len(hospitals_all),
        "n_physicians": int(df["physician"].nunique()),
        "n_procedures": int(df["procedure"].nunique()),
        "active_hospitals": int(ytd_cy["hospital"].nunique()),
        "active_physicians": int(ytd_cy["physician"].nunique()),
    }

    hospital_ranking_detail = []
    for h in hospitals_all:
        h_ytd = ytd_cy[ytd_cy["hospital"] == h]
        h_ly = ytd_ly[ytd_ly["hospital"] == h]
        if len(h_ytd) == 0:
            continue
        hospital_ranking_detail.append({
            "hospital": h,
            "count": int(len(h_ytd)),
            "md_count": int(h_ytd["physician"].nunique()),
            "pct_of_territory": round(len(h_ytd) / region_ytd_total * 100) if region_ytd_total else 0,
            "count_ly": int(len(h_ly)),
        })
    hospital_ranking_detail.sort(key=lambda x: -x["count"])

    # Varipulse adoption denominator = AF/Con. AF cases ∪ any non-AF case that used Varipulse
    _af_group = ["AF", "Con. AF"]
    af_mtd = mtd_cy[mtd_cy["procedure"].isin(_af_group) | mtd_cy["is_varipulse"]]
    af_ytd = ytd_cy[ytd_cy["procedure"].isin(_af_group) | ytd_cy["is_varipulse"]]

    def _vari_entry(sub_m, sub_y):
        return {
            "mtd": {"af": int(len(sub_m)), "varipulse": int(sub_m["is_varipulse"].sum())},
            "ytd": {"af": int(len(sub_y)), "varipulse": int(sub_y["is_varipulse"].sum())},
        }

    varipulse_adoption_region = _vari_entry(af_mtd, af_ytd)
    varipulse_adoption = {h: _vari_entry(af_mtd[af_mtd["hospital"] == h], af_ytd[af_ytd["hospital"] == h]) for h in hospitals_all}

    varipulse_adoption_phys = {}
    for p in df["physician"].unique():
        af_m_p = af_mtd[af_mtd["physician"] == p]
        af_y_p = af_ytd[af_ytd["physician"] == p]
        entry = {"__all__": _vari_entry(af_m_p, af_y_p)}
        for h in ytd_cy[ytd_cy["physician"] == p]["hospital"].unique():
            entry[h] = _vari_entry(af_m_p[af_m_p["hospital"] == h], af_y_p[af_y_p["hospital"] == h])
        varipulse_adoption_phys[p] = entry

    phys_ytd_grouped = ytd_cy.groupby("physician").size().sort_values(ascending=False).head(10)
    physician_ranking_detail = []
    for p, c in phys_ytd_grouped.items():
        physician_ranking_detail.append({
            "physician": p,
            "count": int(c),
            "count_ly": int(len(ytd_ly[ytd_ly["physician"] == p])),
        })

    phys_hospitals_grouped = (
        ytd_cy.groupby(["physician", "hospital"])
        .size()
        .reset_index(name="count")
        .sort_values(["physician", "count"], ascending=[True, False])
    )
    primary = {}
    for _, r in phys_hospitals_grouped.iterrows():
        if r["physician"] not in primary:
            primary[r["physician"]] = r["hospital"]
    for p in df["physician"].unique():
        if p not in primary:
            sub = df[df["physician"] == p].groupby("hospital").size().sort_values(ascending=False)
            if len(sub) > 0:
                primary[p] = sub.index[0]

    def rows(grp, **fields):
        return [{**{k: v for k, v in zip(fields.keys(), key) if not callable(v)}, "count": int(c)}
                for key, c in grp.items()]

    agg = {
        "meta": meta,
        "region_monthly": [{"ym": ym, "count": int(c)} for ym, c in df.groupby("ym").size().sort_index().items()],
        "region_mtd_current": int(len(mtd_cy)),
        "region_mtd_ly": int(len(mtd_ly)),
        "region_mtd_ly_full": int(len(mtd_ly_full)),
        "region_ytd_current": region_ytd_total,
        "region_ytd_ly": int(len(ytd_ly)),
        "region_procedure_ytd": [{"procedure": p, "count": int(c)} for p, c in ytd_cy["procedure"].value_counts().items()],
        "region_procedure_ytd_ly": [{"procedure": p, "count": int(c)} for p, c in ytd_ly["procedure"].value_counts().items()],
        "hospital_ranking_detail": hospital_ranking_detail,
        "varipulse_adoption": varipulse_adoption,
        "varipulse_adoption_region": varipulse_adoption_region,
        "varipulse_adoption_phys": varipulse_adoption_phys,
        "physician_ranking_detail": physician_ranking_detail,
        "hospital_monthly": [{"hospital": h, "ym": ym, "count": int(c)} for (h, ym), c in df.groupby(["hospital", "ym"]).size().sort_index().items()],
        "hospital_procedure_ytd": [{"hospital": h, "procedure": p, "count": int(c)} for (h, p), c in ytd_cy.groupby(["hospital", "procedure"]).size().items()],
        "hospital_physician_ytd": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in ytd_cy.groupby(["hospital", "physician"]).size().items()],
        "hospital_physician_monthly": [{"hospital": h, "physician": p, "ym": ym, "count": int(c)} for (h, p, ym), c in df.groupby(["hospital", "physician", "ym"]).size().sort_index().items()],
        "hospital_physician_procedure_ytd": [{"hospital": h, "physician": p, "procedure": pr, "count": int(c)} for (h, p, pr), c in ytd_cy.groupby(["hospital", "physician", "procedure"]).size().items()],
        "hospital_ytd_ranking": [{"hospital": h["hospital"], "count": h["count"]} for h in hospital_ranking_detail],
        "mtd_current": [{"hospital": h, "count": int(c)} for h, c in mtd_cy.groupby("hospital").size().items()],
        "mtd_ly": [{"hospital": h, "count": int(c)} for h, c in mtd_ly.groupby("hospital").size().items()],
        "mtd_ly_full": [{"hospital": h, "count": int(c)} for h, c in mtd_ly_full.groupby("hospital").size().items()],
        "ytd_current": [{"hospital": h, "count": int(c)} for h, c in ytd_cy.groupby("hospital").size().items()],
        "ytd_ly": [{"hospital": h, "count": int(c)} for h, c in ytd_ly.groupby("hospital").size().items()],
        "phys_mtd_current": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in mtd_cy.groupby(["hospital", "physician"]).size().items()],
        "phys_mtd_ly": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in mtd_ly.groupby(["hospital", "physician"]).size().items()],
        "phys_mtd_ly_full": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in mtd_ly_full.groupby(["hospital", "physician"]).size().items()],
        "phys_ytd_current": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in ytd_cy.groupby(["hospital", "physician"]).size().items()],
        "phys_ytd_ly": [{"hospital": h, "physician": p, "count": int(c)} for (h, p), c in ytd_ly.groupby(["hospital", "physician"]).size().items()],
        "phys_all_ytd_ranking": [{"physician": p, "count": int(c)} for p, c in ytd_cy.groupby("physician").size().sort_values(ascending=False).items()],
        "phys_monthly_all": [{"physician": p, "ym": ym, "count": int(c)} for (p, ym), c in df.groupby(["physician", "ym"]).size().sort_index().items()],
        "phys_procedure_ytd_all": [{"physician": p, "procedure": pr, "count": int(c)} for (p, pr), c in ytd_cy.groupby(["physician", "procedure"]).size().items()],
        "phys_mtd_all": [{"physician": p, "count": int(c)} for p, c in mtd_cy.groupby("physician").size().items()],
        "phys_mtd_ly_all": [{"physician": p, "count": int(c)} for p, c in mtd_ly.groupby("physician").size().items()],
        "phys_mtd_ly_full_all": [{"physician": p, "count": int(c)} for p, c in mtd_ly_full.groupby("physician").size().items()],
        "phys_ytd_all": [{"physician": p, "count": int(c)} for p, c in ytd_cy.groupby("physician").size().items()],
        "phys_ytd_ly_all": [{"physician": p, "count": int(c)} for p, c in ytd_ly.groupby("physician").size().items()],
        "phys_hospitals": [{"physician": r["physician"], "hospital": r["hospital"], "count": int(r["count"])} for _, r in phys_hospitals_grouped.iterrows()],
        "physician_primary_hospital": [{"physician": p, "hospital": h} for p, h in primary.items()],
    }

    df_sorted = df.iloc[::-1].sort_values("date", ascending=False, kind="mergesort")

    def _fmt_row(r):
        return {
            "date": _short_date(r["date"]),
            "year": int(r["date"].year),
            "hospital": r["hospital"],
            "physician_dr": _dr_lastname(r["physician"]),
            "type": r["procedure"],
            "cas": _first_name(r["cas"]),
            "vp": bool(r["is_varipulse"]),
        }

    def _recent_slice(sub):
        cy = sub[sub["year"] == last_year]
        py_tail = sub[sub["year"] < last_year].head(30)
        return pd.concat([cy, py_tail])

    agg["recent_cases_by_hospital"] = {
        h: [_fmt_row(r) for _, r in _recent_slice(df_sorted[df_sorted["hospital"] == h]).iterrows()]
        for h in hospitals_all
    }
    by_phys = {}
    for p in df["physician"].unique():
        sub = df_sorted[df_sorted["physician"] == p]
        per_hosp = {
            h: [_fmt_row(r) for _, r in _recent_slice(sub[sub["hospital"] == h]).iterrows()]
            for h in sub["hospital"].unique()
        }
        per_hosp["__all__"] = [_fmt_row(r) for _, r in _recent_slice(sub).iterrows()]
        by_phys[p] = per_hosp
    agg["recent_cases_by_physician"] = by_phys

    issues = []
    last_day_raw = int((df["date"].dt.normalize() == last_date.normalize()).sum())
    last_day_ytd = int((ytd_cy["date"].dt.normalize() == last_date.normalize()).sum())
    if last_day_raw != last_day_ytd:
        issues.append(f"YTD missing {last_day_raw - last_day_ytd} cases on {last_date.date()} (raw={last_day_raw}, ytd={last_day_ytd})")

    sum_phys = sum(x["count"] for x in agg["phys_ytd_all"])
    sum_proc = sum(x["count"] for x in agg["region_procedure_ytd"])
    sum_hosp = sum(x["count"] for x in agg["hospital_ranking_detail"])
    if sum_phys != region_ytd_total:
        issues.append(f"phys_ytd_all sum ({sum_phys}) != region YTD ({region_ytd_total})")
    if sum_proc != region_ytd_total:
        issues.append(f"region_procedure_ytd sum ({sum_proc}) != region YTD ({region_ytd_total})")
    if sum_hosp != region_ytd_total:
        issues.append(f"hospital_ranking_detail sum ({sum_hosp}) != region YTD ({region_ytd_total})")

    phys_ytd_map = {x["physician"]: x["count"] for x in agg["phys_ytd_all"]}
    for p, per_hosp in by_phys.items():
        recent_ytd = sum(1 for r in per_hosp.get("__all__", []) if r["year"] == last_year)
        kpi_ytd = phys_ytd_map.get(p, 0)
        if recent_ytd > kpi_ytd:
            issues.append(f"{p}: recent_cases YTD ({recent_ytd}) > KPI YTD ({kpi_ytd})")

    agg["_sanity_issues"] = issues
    return agg


# ---------------------------------------------------------------------------
# Render
# ---------------------------------------------------------------------------

def load_bw_svg(path="resource/biosense-webster-inc-logo-vector.svg"):
    try:
        with open(path, "r", encoding="utf-8") as f:
            svg = f.read()
    except FileNotFoundError:
        return ""
    svg = svg.replace("#38404A", "#ffffff")
    svg = svg.replace('viewBox="-153 -46 652 652"', 'viewBox="-150 195 620 118"')
    svg = svg.replace("<svg ", '<svg style="width:100%;height:auto;display:block" ', 1)
    return svg


def load_png_b64(path):
    """Load PNG and strip EXIF (Affinity exports may embed Orientation tag
    that browsers honor — causes images to render rotated)."""
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        return ""
    try:
        from PIL import Image
        from io import BytesIO
        img = Image.open(BytesIO(raw))
        clean = img.copy()
        buf = BytesIO()
        clean.save(buf, format="PNG", optimize=True)
        raw = buf.getvalue()
    except ImportError:
        pass
    return base64.b64encode(raw).decode("ascii")


def render_html(agg, template=HTML_TEMPLATE):
    json_str = json.dumps(agg, separators=(",", ":"), ensure_ascii=False)
    out = template
    out = out.replace("{{FAVICON_B64}}", FAVICON_B64)
    out = out.replace("{{HLOGO_B64}}", HLOGO_B64)
    out = out.replace("{{BW_LOGO_B64}}", BW_LOGO_B64)
    out = out.replace("{{BW_SVG}}", load_bw_svg())
    out = out.replace("{{ALL_GAS_B64}}", load_png_b64("resource/all-gas.png"))
    out = out.replace("{{NO_BRAKES_B64}}", load_png_b64("resource/no-brakes-12.png"))
    out = out.replace("{{JSON_DATA}}", json_str)
    return out


