def backup_src(today, last_date):
    """Commit and push src/ to its private repo. Never fatal: the dashboard is
    already published by this point, so a backup failure is only a warning."""
    src_dir = Path(__file__).resolve().parent / "src"
    if not (src_dir / ".git").exists():
        print(f"      Skipped — src/ is not a git repo.")
        return
    git = ["git", "-C", str(src_dir)]
    try:
        subprocess.run(git + ["add", "-A"], check=True)
        if subprocess.run(git + ["diff", "--cached", "--quiet"]).returncode == 0:
            print(f"      No new exports to back up.")
            return
        subprocess.run(git + ["commit", "-m", f"case data {today} (through {last_date})"], check=True)
        subprocess.run(git + ["push"], check=True)
        print(f"      ✓ Pushed to private repo.")
    except subprocess.CalledProcessError as e:
        print(f"      ⚠ Backup failed ({e}). Dashboard was published; retry with:")
        print(f"        cd src && git add -A && git commit -m 'case data {today}' && git push")


def main():
    import os
    os.system("clear")
    parser = argparse.ArgumentParser(description="Build EP Case Dashboard HTML from Salesforce xlsx export")
    parser.add_argument("xlsx", nargs="?", help="Path to Salesforce xlsx export (omit to auto-pick newest in src/)")
    parser.add_argument("--push", action="store_true", help="Git commit and push after writing")
    args = parser.parse_args()

    if args.xlsx:
        xlsx_path = args.xlsx
    else:
        candidates = sorted(
            (f for f in glob.glob("src/*.xlsx") if not Path(f).name.startswith("~$")),
            key=lambda f: Path(f).stat().st_mtime,
        )
        if not candidates:
            print("ERROR: No .xlsx files found in src/. Pass the path explicitly.")
            sys.exit(1)
        xlsx_path = candidates[-1]
        print("==================================================================")
        print(f"      Auto-detected: {xlsx_path}")
        print("==================================================================")

    import os
    today = datetime.now().strftime("%Y-%m-%d")
    os.makedirs("dest", exist_ok=True)
    dated_path = f"dest/EP_Dashboard_{today}.html"

    print(f"[1/4] Reading Excel file: {xlsx_path}")
    df = load_data(xlsx_path)
    meta_preview = df['date'].min().strftime('%Y-%m-%d'), df['date'].max().strftime('%Y-%m-%d')
    print(f"      {len(df)} rows loaded  |  date range: {meta_preview[0]} → {meta_preview[1]}")
    print(f"      Hospitals: {df['hospital'].nunique()}  |  Physicians: {df['physician'].nunique()}  |  Procedures: {df['procedure'].nunique()}")

    print("\n==================================================================")
    print(f"[2/4] Computing aggregates ...")
    agg = compute_aggregates(df)
    m = agg['meta']
    print(f"      Last case date : {m['last_date']}")
    print(f"      YTD cases      : {agg['region_ytd_current']}  (LY same period: {agg['region_ytd_ly']})")
    print(f"      MTD cases      : {agg['region_mtd_current']}  (LY same period: {agg['region_mtd_ly']})")
    print(f"      Active hospitals  : {m['active_hospitals']} / {m['n_hospitals']}")
    print(f"      Active physicians : {m['active_physicians']} / {m['n_physicians']}")

    issues = agg.pop("_sanity_issues", [])
    if issues:
        print(f"\n      ⚠️  Sanity check found {len(issues)} issue(s):")
        for i in issues:
            print(f"        - {i}")
    else:
        print(f"      ✓ Sanity checks passed")

    print("\n==================================================================")
    print(f"[3/4] Rendering HTML ...")
    html_out = render_html(agg)

    print("\n==================================================================")
    print(f"[4/4] Writing files ...")
    for path in ["index.html", dated_path]:
        with open(path, "w", encoding="utf-8") as f:
            f.write(html_out)
        size_kb = len(html_out.encode()) // 1024
        print(f"      {path}  ({size_kb} KB)")

    if args.push:
        print("\n==================================================================")
        print(f"[5/6] Pushing dashboard to GitHub ...")
        subprocess.run(["git", "add", "index.html", dated_path], check=True)
        staged = subprocess.run(["git", "diff", "--cached", "--quiet"])
        if staged.returncode == 0:
            print(f"      No changes to commit (files already up to date).")
        else:
            subprocess.run(["git", "commit", "-m", f"dashboard update {today} (data through {m['last_date']})"], check=True)
            subprocess.run(["git", "push"], check=True)

        print("\n==================================================================")
        print(f"[6/6] Backing up src/ to private repo ...")
        backup_src(today, m["last_date"])

        print("\n==================================================================")
        print(f"✓ Done!  Live URL → https://rennmin84.github.io/ep-dashboard/")
        print("==================================================================\n\n")
    else:
        print("\n==================================================================")
        print(f"✓ Done!  (Add --push to publish to GitHub Pages)")
        print("==================================================================\n\n")


if __name__ == "__main__":
    main()
